const entitiesHelp = "alexandria_delete_application alexandria_get_application alexandria_get_category client_version cni deployment_group dex_remote_command dex_rule dex_synthetic_application_monitoring digital_experience_monitoring_device digital_experience_monitoring_dex_delete_response_collection digital_experience_monitoring_dex_response_collection digital_experience_monitoring_dex_single digital_experience_monitoring_fleet_status_device digital_experience_monitoring_fleet_status_live digital_experience_monitoring_fleet_status_over_time integration interconnect ip_profile list location nsc_cni nsc_default_name nsc_interconnect nsc_setting nsc_slot_info nsc_status_info one_application_detail one_integration_create one_integration_detail one_integration_pause one_integration_resume one_integration_update one_paginated_application_list_list one_paginated_auth_method_detail_list one_paginated_integration_v2_list_item_list one_paginated_setup_flow_list override_code pacfile physical_device proxy_endpoint registration rule teams_devices_api_response_single teams_devices_components_schemas_response_collection teams_devices_components_schemas_single teams_devices_default_device_setting teams_devices_device teams_devices_device_setting teams_devices_device_settings_response_collection teams_devices_devices_policy_certificates_single teams_devices_fallback_domain_response_collection teams_devices_global_warp_override teams_devices_id teams_devices_override_code teams_devices_response_collection teams_devices_schemas_id teams_devices_schemas_response_collection teams_devices_schemas_single teams_devices_single teams_devices_split_tunnel_include_response_collection teams_devices_split_tunnel_response_collection teams_devices_zero_trust_account_device_setting tunnel tunnel_cfd_tunnel_response_collection tunnel_cfd_tunnel_response_single tunnel_configuration tunnel_empty tunnel_hostname_route_response_collection tunnel_hostname_route_response_single tunnel_mesh_configuration_response_single tunnel_route_response_single tunnel_subnet_response_collection tunnel_subnet_response_single tunnel_subnet_response_single_nullable tunnel_teamnet_response_collection tunnel_teamnet_response_single tunnel_tunnel_client tunnel_tunnel_connection tunnel_tunnel_response_token tunnel_tunnel_warp_connector_client tunnel_tunnel_warp_connector_connection tunnel_vnet_response_collection tunnel_vnet_response_single tunnel_warp_connector_response_collection tunnel_warp_connector_response_single tunnel_zero_trust_connectivity_setting warp warp_change_event warp_teams_device_api_other zero_trust_gateway_applications_review_status zero_trust_gateway_csv_operation_single zero_trust_gateway_custom_certificate_setting zero_trust_gateway_gateway_account zero_trust_gateway_gateway_account_config zero_trust_gateway_gateway_account_egress_cidr_pair_list zero_trust_gateway_gateway_account_logging_setting zero_trust_gateway_list_item_response_collection zero_trust_gateway_list_single zero_trust_gateway_response_collection zero_trust_gateway_response_collection_10 zero_trust_gateway_response_collection_2 zero_trust_gateway_response_collection_3 zero_trust_gateway_response_collection_4 zero_trust_gateway_response_collection_5 zero_trust_gateway_response_collection_6 zero_trust_gateway_response_collection_7 zero_trust_gateway_response_collection_8 zero_trust_gateway_response_collection_9 zero_trust_gateway_single zero_trust_gateway_single_response_2 zero_trust_gateway_single_response_3 zero_trust_gateway_single_response_4 zero_trust_gateway_single_response_5 zero_trust_gateway_single_response_6 zero_trust_gateway_single_response_7 zero_trust_gateway_single_response_with_list_item zero_trust_risk_scoring zero_trust_risk_scoring_integration"

func main() {
	os.Exit(run(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
}

// usage prints the CLI help (for --help / -h). No client or network setup.
func usage(out io.Writer) {
	fmt.Fprintf(out, "%s-cli — boru-driven CLI + REPL for the %s SDK\n\n", prompt, prompt)
	fmt.Fprintln(out, "Usage:")
	fmt.Fprintf(out, "  %s-cli [--help] [<boru expression>]\n\n", prompt)
	fmt.Fprintln(out, "With arguments, they are joined into a single boru expression and")
	fmt.Fprintln(out, "evaluated against the API. With no arguments, starts an interactive REPL.")
	fmt.Fprintln(out)
	fmt.Fprintln(out, "Words:    list / load / update <query?> <entity>")
	fmt.Fprintln(out, "Entities:", entitiesHelp)
	fmt.Fprintln(out, "Env:      CLOUDFLARE_ZERO_TRUST_APIKEY (api key), CLOUDFLARE_ZERO_TRUST_BASE (base url override)")
	fmt.Fprintln(out, "REPL:     /help  /quit")
}

func run(args []string, in io.Reader, out, errOut io.Writer) int {
	// --help / -h: print usage and exit before any config or network setup.
	for _, a := range args {
		if a == "--help" || a == "-h" {
			usage(out)
			return 0
		}
	}

	// Configure from the environment: CLOUDFLARE_ZERO_TRUST_APIKEY carries the API key and
	// CLOUDFLARE_ZERO_TRUST_BASE optionally overrides the API base URL (e.g. production).
	// Both injectable by a secrets vault. Unset -> nil config defaults.
	var opts map[string]any
	if apikey := os.Getenv("CLOUDFLARE_ZERO_TRUST_APIKEY"); apikey != "" {
		opts = map[string]any{"apikey": apikey}
	}
	if base := os.Getenv("CLOUDFLARE_ZERO_TRUST_BASE"); base != "" {
		if opts == nil {
			opts = map[string]any{}
		}
		opts["base"] = base
	}
	client := sdk.NewCloudflareZeroTrustSDK(opts)

	r, err := eng.NewRegistry()
	if err != nil {
		fmt.Fprintf(errOut, "registry: %v\n", err)
		return 1
	}
	registerSDKWords(r, client)
	if err := r.Err(); err != nil {
		fmt.Fprintf(errOut, "word registration: %v\n", err)
		return 1
	}
	r.SetParseFunc(parser.Parse)
	r.InitRootContext()
	r.MarkReady()

	if len(args) > 0 {
		return evalOnce(r, strings.Join(args, " "), out, errOut)
	}
	repl(r, in, out)
	return 0
}

func evalOnce(r *eng.Registry, src string, out, errOut io.Writer) int {
	values, err := parser.Parse(src)
	if err != nil {
		fmt.Fprintf(errOut, "parse: %v\n", err)
		return 1
	}
	result, err := eng.NewTop(r).Run(values)
	if err != nil {
		fmt.Fprintf(errOut, "error: %v\n", err)
		return 1
	}
	for _, v := range result {
		fmt.Fprintln(out, v.String())
	}
	return 0
}

func repl(r *eng.Registry, in io.Reader, out io.Writer) {
	scanner := bufio.NewScanner(in)
	scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	for {
		fmt.Fprintf(out, "%s> ", prompt)
		if !scanner.Scan() {
			fmt.Fprintln(out)
			return
		}
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		switch line {
		case "/quit", "/q", "/exit":
			return
		case "/help", "/h", "/?":
			fmt.Fprintln(out, "words:    list / load / update <query?> <entity>")
			fmt.Fprintln(out, "entities:", entitiesHelp)
			fmt.Fprintln(out, "meta:     /help  /quit")
			continue
		}
		values, err := parser.Parse(line)
		if err != nil {
			fmt.Fprintf(out, "  parse error: %v\n", err)
			continue
		}
		result, err := eng.NewTop(r).Run(values)
		if err != nil {
			fmt.Fprintf(out, "  error: %v\n", err)
			continue
		}
		for _, v := range result {
			fmt.Fprintln(out, v.String())
		}
	}
}
